CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,name TEXT,color TEXT,bday TEXT,username TEXT UNIQUE COLLATE NOCASE,salt TEXT,hash TEXT,bio TEXT DEFAULT '',role TEXT DEFAULT 'Member',avatar TEXT DEFAULT '',banner TEXT DEFAULT '',extra TEXT DEFAULT '{}',upd INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT,ts INTEGER,ua TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,channel TEXT,user_id TEXT,body TEXT,ts INTEGER,att TEXT DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_msg ON messages(channel,id);
CREATE TABLE IF NOT EXISTS finance(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,type TEXT,details TEXT,amount REAL,date TEXT,ts INTEGER,cat TEXT DEFAULT 'other',split TEXT DEFAULT '[]',note TEXT DEFAULT '',to_id TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,date TEXT,user_id TEXT,edate TEXT DEFAULT '',st TEXT DEFAULT '',en TEXT DEFAULT '',allday INTEGER DEFAULT 1,cat TEXT DEFAULT 'other',note TEXT DEFAULT '',members TEXT DEFAULT '[]',rep TEXT DEFAULT 'none');
CREATE TABLE IF NOT EXISTS seen(user_id TEXT PRIMARY KEY,ts INTEGER,act INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS voice(channel TEXT,user_id TEXT,ts INTEGER,PRIMARY KEY(channel,user_id));
CREATE TABLE IF NOT EXISTS signals(id INTEGER PRIMARY KEY AUTOINCREMENT,from_id TEXT,to_id TEXT,type TEXT,data TEXT,ts INTEGER);
CREATE TABLE IF NOT EXISTS qr(token TEXT PRIMARY KEY,status TEXT,user_id TEXT,ts INTEGER);
CREATE TABLE IF NOT EXISTS clips(id INTEGER PRIMARY KEY AUTOINCREMENT,from_id TEXT,to_key TEXT,data TEXT,dur REAL,ts INTEGER,txt TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS kv(k TEXT PRIMARY KEY,v TEXT);
CREATE TABLE IF NOT EXISTS push_subs(endpoint TEXT PRIMARY KEY,user_id TEXT,ts INTEGER);
CREATE TABLE IF NOT EXISTS notifs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,title TEXT,body TEXT,tag TEXT,ts INTEGER,done INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS media(id TEXT,seq INTEGER,ch TEXT,mime TEXT,data TEXT,user_id TEXT,ts INTEGER,PRIMARY KEY(id,seq));
CREATE TABLE IF NOT EXISTS emojis(name TEXT PRIMARY KEY,data TEXT,user_id TEXT,ts INTEGER);
CREATE TABLE IF NOT EXISTS locs(user_id TEXT PRIMARY KEY,lat REAL,lng REAL,acc REAL,ts INTEGER,share INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS trips(user_id TEXT PRIMARY KEY,dest TEXT,lat REAL,lng REAL,slat REAL,slng REAL,mode TEXT,fare REAL,eta INTEGER,start_ts INTEGER,status TEXT);
CREATE TABLE IF NOT EXISTS albums(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,user_id TEXT,ts INTEGER);
CREATE TABLE IF NOT EXISTS album_items(id INTEGER PRIMARY KEY AUTOINCREMENT,album_id INTEGER,user_id TEXT,t TEXT,media_id TEXT,mime TEXT,w INTEGER,h INTEGER,dur REAL,th TEXT,caption TEXT,ts INTEGER);
CREATE INDEX IF NOT EXISTS idx_albi ON album_items(album_id,id);
